USE cinema;
SET NAMES utf8mb4;
CREATE TABLE movies(id INT PRIMARY KEY AUTO_INCREMENT,title VARCHAR(150) NOT NULL,genre VARCHAR(100) NOT NULL,duration INT NOT NULL CHECK(duration>0),description TEXT NOT NULL,poster VARCHAR(100) NOT NULL) ENGINE=InnoDB;
CREATE TABLE rooms(id INT PRIMARY KEY AUTO_INCREMENT,name VARCHAR(50) NOT NULL UNIQUE) ENGINE=InnoDB;
CREATE TABLE seats(id INT PRIMARY KEY AUTO_INCREMENT,room_id INT NOT NULL,row_label CHAR(1) NOT NULL,seat_number INT NOT NULL CHECK(seat_number>0),UNIQUE(room_id,row_label,seat_number),FOREIGN KEY(room_id) REFERENCES rooms(id)) ENGINE=InnoDB;
CREATE TABLE showtimes(id INT PRIMARY KEY AUTO_INCREMENT,movie_id INT NOT NULL,room_id INT NOT NULL,starts_at DATETIME NOT NULL,price INT NOT NULL CHECK(price>0),UNIQUE(room_id,starts_at),FOREIGN KEY(movie_id) REFERENCES movies(id),FOREIGN KEY(room_id) REFERENCES rooms(id)) ENGINE=InnoDB;
CREATE TABLE bookings(id INT PRIMARY KEY AUTO_INCREMENT,code VARCHAR(24) NOT NULL UNIQUE,showtime_id INT NOT NULL,customer_name VARCHAR(100) NOT NULL,customer_email VARCHAR(254) NOT NULL,total INT NOT NULL CHECK(total>0),payment_status ENUM('simulated') NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE(id,showtime_id),FOREIGN KEY(showtime_id) REFERENCES showtimes(id)) ENGINE=InnoDB;
CREATE TABLE booking_seats(booking_id INT NOT NULL,showtime_id INT NOT NULL,seat_id INT NOT NULL,unit_price INT NOT NULL CHECK(unit_price>0),PRIMARY KEY(booking_id,seat_id),UNIQUE(showtime_id,seat_id),FOREIGN KEY(booking_id,showtime_id) REFERENCES bookings(id,showtime_id),FOREIGN KEY(seat_id) REFERENCES seats(id),FOREIGN KEY(showtime_id) REFERENCES showtimes(id)) ENGINE=InnoDB;
INSERT INTO movies VALUES(1,'Hành trình vũ trụ','Khoa học viễn tưởng',120,'Đoàn thám hiểm đi tìm tín hiệu bí ẩn giữa các vì sao. Phim mẫu phục vụ demo.','/posters/space.svg'),(2,'Mùa hè đáng nhớ','Tình cảm',100,'Ba người bạn trở về miền biển, cùng viết nên một mùa hè đầy kỷ niệm. Phim mẫu phục vụ demo.','/posters/summer.svg'),(3,'Bí mật thành phố','Trinh thám',110,'Một thám tử lần theo dấu vết trong thành phố không ngủ. Phim mẫu phục vụ demo.','/posters/city.svg');
INSERT INTO rooms VALUES(1,'Phòng 01'),(2,'Phòng 02');
INSERT INTO seats(room_id,row_label,seat_number) SELECT r.id,a.label,b.n FROM rooms r CROSS JOIN (SELECT 'A' label UNION SELECT 'B' UNION SELECT 'C' UNION SELECT 'D' UNION SELECT 'E') a CROSS JOIN (SELECT 1 n UNION SELECT 2 UNION SELECT 3 UNION SELECT 4 UNION SELECT 5 UNION SELECT 6 UNION SELECT 7 UNION SELECT 8) b ORDER BY r.id,a.label,b.n;
INSERT INTO showtimes(movie_id,room_id,starts_at,price) SELECT m.id,r.id,TIMESTAMP(DATE_ADD(CURDATE(),INTERVAL d.n DAY),MAKETIME(10+m.id*3+(r.id-1),0,0)),70000+(r.id-1)*20000 FROM movies m CROSS JOIN rooms r CROSS JOIN (SELECT 1 n UNION SELECT 2 UNION SELECT 3 UNION SELECT 4 UNION SELECT 5 UNION SELECT 6 UNION SELECT 7) d;
